    # Multiplies a vector by a scalar if $type is a scale
    # or Compute the Dot product if $type is an object.
    if {[tomato::helper::IsaObject $type]} {
        return [my DotProduct $other]
    } else {

        set vx [expr {$_x * $type}]
        set vy [expr {$_y * $type}]
        set vz [expr {$_z * $type}]

        return [tomato::mathvec3d::Vector3d new $vx $vy $vz]

